//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF20504.xml";
scwin.vJobMode = "";
scwin.vIsurCd = "";
scwin.vSeq = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "DELIB_COMITE_TP_CD",
        cnm: "cmb_DelibComiteTpCd"
    }, {
        cid: "DELIST_DELIB_CHRGTEAM_TP_CD",
        cnm: "cmb_ChrgDepCd"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='DELIB_COMITE_TP_CD','DELIST_DELIB_CHRGTEAM_TP_CD'";
    dts_Code.DataID = encodeURI(url);
    dts_Code.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Code.getTotalRow(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
    //
    strCbd = "";
    strCbd = strCbd + ',Y' + "^" + '상장유지';
    strCbd = strCbd + ',D' + "^" + '상장폐지';
    cmb_ListComiteDelibRsltCd.CBData = strCbd;

    //
    /*strCbd = 'N' + "^" + '미대상';
    strCbd = strCbd + ',Y' + "^" + '대상';
    cmb_OpnReservYn.CBData = strCbd;
    cmb_OpnReservYn.Index = 0;*/

};
scwin.fn_getDelistMtbk = function() {
    trs_Read.Action = "/DelistMtbk.do?method=getDelistMtbk" + "&ISUR_CD=" + scwin.vIsurCd + "&SEQ=" + scwin.vSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_ContentsInfo,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    if (dts_fileList.getCellData(1, "fileInfo") == "") {
        dts_fileList.Reset();
    }
    if (txb_ISUR_CD.getValue() == "") {
        $c.win.alert("'회사코드(명)'을 입력하세요.");
        return;
    }
    if (med_ComiteDd.getValue() == "") {
        $c.win.alert("'회의일'을 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DelibComiteTpCd) == "") {
        $c.win.alert("'심의 위원회'를 입력하세요.");
        return;
    }
    var rtn = confirm('등록 하시겠습니까?');
    if (rtn == 1) {
        dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
        trs_Save.Action = "/DelistMtbk.do?method=insertDelistMtbk" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_ContentsInfo,I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    if (txb_ISUR_CD.getValue() == "") {
        $c.win.alert("'회사코드(명)'을 입력하세요.");
        return;
    }
    if (med_ComiteDd.getValue() == "") {
        $c.win.alert("'회의일'을 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DelibComiteTpCd) == "") {
        $c.win.alert("'심의 위원회'를 입력하세요.");
        return;
    }
    var rtn = confirm('수정 하시겠습니까?');
    if (rtn == 1) {
        dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
        trs_Update.Action = "/DelistMtbk.do?method=updateDelistMtbk&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyValue = "JSP(I:pInput=dts_ContentsInfo,I:pFile=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) {

        //dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ContentsDel.insertRow();
        trs_Delete.Action = "/DelistMtbk.do?method=deleteDelistMtbk&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_ContentsDel)";
        trs_Delete.Parameters = "ISUR_CD=" + dts_ContentsInfo.getCellData(1, "ISUR_CD") + ",SEQ=" + dts_ContentsInfo.getCellData(1, "SEQ") + ",REG_ID=" + js_emp_no;
        trs_Delete.Post();
    }
};
scwin.fn_setFileDataHeader = function() {
    dts_fileList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELIST_MTBK_ATTACH_INOUT";
    dts_fileList.Reset();
};
scwin.fn_SetSaveHeader = function() {
    dts_ContentsInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELIST_MTBK_INOUT";
    dts_ContentsInfo.Reset();
    dts_ContentsInfo.insertRow();
    dts_ContentsInfo.setCellData(1, "OPN_RESERV_YN", 'N'); // 기본값

};
scwin.fn_filedown = function() {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&ISUR_CD=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "ISUR_CD") + "&SEQ=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "SEQ") + "&ATTACH_SEQ=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") + "&gubun=40";
};
scwin.fn_ShowCalendar = function(o) {
    if ((o != undefined) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.trs_count_OnSuccess = function() {
    $c.win.alert('trs_count.OnSuccess()');
};
scwin.trs_count_OnFail = function() {
    $c.win.alert(trs_count.ErrorMsg);
};
scwin.dts_ContentsInfo_OnLoadError = function() {
    $c.win.alert('dts_ContentsInfo.OnLoadError()');
};
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        //setObjectValue(cmb_DelibComiteTpCd, dts_ContentsInfo.NameString(0,"DELIB_COMITE_TP_CD"));

        //setObjectValue(cmb_ListComiteDelibRsltCd, dts_ContentsInfo.NameString(0,"LIST_COMITE_DELIB_RSLT_CD"));

    }
};
scwin.btn_save_onclick = function() {
    if (scwin.vJobMode == "I") {
        scwin.fn_save();
    }
    if (scwin.vJobMode == "M") {
        scwin.fn_update();
    }
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
    if (scwin.vJobMode == "I") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileList.getTotalRow() == 5) {
        $c.win.alert("첨부파일은 최대 5건 입니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (scwin.vJobMode == "I") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "OPN_YN", 'Y');
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            var seq = dts_fileList.getRowPosition();
            for (i = 0; i < dts_fileList.getTotalRow(); i++) {
                if (dts_fileList.getCellData(i, "ATTACH_SEQ") == seq) {
                    seq++;
                    i = 0;
                }
            }
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", seq);
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ISUR_CD", scwin.vIsurCd);
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "SEQ", scwin.vSeq);
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "REG_ID", js_emp_no);
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "OPN_YN", 'Y');
            file_name.setValue(inf_find.getValue());
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0 && dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename") != "" && dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") != "") {
        scwin.fn_filedown();
    }
};
scwin.img_SetComiteDd_onclick = function() {
    scwin.fn_ShowCalendar(med_ComiteDd);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_searchCode();
    scwin.vJobMode = $c.frame.path("../").scwin.vJobMode;
    if (scwin.vJobMode == "M") {
        $c.stf.showObj(img_com_srch, false);
        getParaIsurCd = $c.frame.path("../").fn_getParaIsurCd;
        scwin.vIsurCd = getParaIsurCd();
        getParaSeq = $c.frame.path("../").fn_getParaSeq;
        scwin.vSeq = getParaSeq();
        scwin.fn_getDelistMtbk();
    }
    if (scwin.vJobMode == "I") {
        scwin.fn_setFileDataHeader();
        scwin.fn_SetSaveHeader();
    }
};
scwin.grd_fileList_CanColumnPosChange = function(row, colid) {
    return true;
};
